// One persistent visual relay carries the outgoing scene's last focal element into the next.
let handoff=null;
function clearHandoff(){if(handoff){const h=handoff;handoff=null;h.anims.forEach(a=>a.cancel());h.node.remove();for(const e of [h.src,h.dest])if(e)e.style.removeProperty('visibility')}}
function onScreen(e){if(!e)return false;const r=e.getBoundingClientRect();return r.width>20&&r.height>12&&r.top>=0&&r.bottom<=innerHeight&&getComputedStyle(e).visibility!=='hidden'}
function focalTitle(stage,scene,direction,out){if(scene==='journey'){const panels=[...stage.querySelectorAll('.scene-panel h3')].filter(onScreen);if(panels.length)return direction>0?(out?panels.at(-1):panels[0]):(out?panels[0]:panels.at(-1))}return [...stage.querySelectorAll('h1,h2,h3')].find(onScreen)||null}
function mediaPair(stage,old,next){if(old==='work'&&next==='project-index'){const a=slides[slideIndex];return {hash:a.hash,src:a.querySelector('img'),reverse:false}}if(old==='project-index'&&next==='work'){const a=document.querySelector('#project-index .project[href="'+slides[slideIndex].hash+'"]');return {hash:slides[slideIndex].hash,src:a?.querySelector('.media img'),reverse:true}}return null}
function titleLayer(el){const c=getComputedStyle(el),n=document.createElement('div');n.className='handoff-title';n.textContent=el.textContent.trim();for(const k of ['fontFamily','fontSize','fontWeight','fontStyle','lineHeight','letterSpacing','color','textAlign'])n.style[k]=c[k];n.style.color='var(--ink)';return n}
function imageLayer(el){const n=el.cloneNode(true);n.removeAttribute('id');n.className='handoff-image';return n}
function boxOf(el){const r=el.getBoundingClientRect();return {left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px'}}
function beginHandoff(stage,old,next,dir){if(!motionOK())return null;const pair=mediaPair(stage,old,next),isImage=!!pair&&onScreen(pair.src);const src=isImage?pair.src:focalTitle(stage,old,dir,true);if(!onScreen(src))return null;const n=document.createElement('div');n.className='continuity-relay'+(isImage?' relay-image':'');n.setAttribute('aria-hidden','true');n.inert=true;const a=isImage?imageLayer(src):titleLayer(src);n.append(a);Object.assign(n.style,boxOf(src));document.body.append(n);src.style.visibility='hidden';const h={node:n,src,old,next,dir,layer:a,anims:[],pair:isImage?pair:null};handoff=h;const r=src.getBoundingClientRect(),dx=dir*28;h.mid={left:(r.left+dx)+'px',top:(r.top-dir*14)+'px',width:r.width+'px',height:r.height+'px'};h.anims.push(n.animate([boxOf(src),h.mid],{duration:1050,easing:'cubic-bezier(.32,.02,.18,1)',fill:'forwards'}));return h}
function finishHandoff(h,stage,next){if(handoff!==h)return;let dest=h.pair?(h.pair.reverse?slides[slideIndex].querySelector('img'):stage.querySelector('.project[href="'+h.pair.hash+'"] .media img')):focalTitle(stage,next,h.dir,false);if(!onScreen(dest)){clearHandoff();return}h.dest=dest;const destBox=boxOf(dest);const second=h.pair?imageLayer(dest):titleLayer(dest);second.style.opacity='0';h.node.append(second);dest.style.visibility='hidden';h.anims.forEach(a=>a.cancel());h.anims=[];Object.assign(h.node.style,h.mid);const d=1550,e='cubic-bezier(.32,.02,.18,1)';h.anims.push(h.node.animate([h.mid,{...destBox}],{duration:d,easing:e,fill:'forwards'}));h.anims.push(h.layer.animate([{opacity:1},{offset:.35,opacity:1},{offset:.72,opacity:0},{opacity:0}],{duration:d,easing:'ease-in-out',fill:'forwards'}));h.anims.push(second.animate([{opacity:0},{offset:.35,opacity:0},{offset:.72,opacity:1},{opacity:1}],{duration:d,easing:'ease-in-out',fill:'forwards'}));h.anims[0].finished.then(()=>{if(handoff===h)clearHandoff()}).catch(()=>{})}
