const name29=document.getElementById('profile-name');function fitName29(){if(root.dataset.scene!=='welcome'){name29.style.removeProperty('--fit-name');return}const width=name29.parentElement.clientWidth;if(!width)return;const canvas=document.createElement('canvas'),cx=canvas.getContext('2d'),style=getComputedStyle(name29);cx.font=`600 100px ${style.fontFamily}`;const measured=cx.measureText(name29.textContent).width;const max=innerWidth<=760?28:54;name29.style.setProperty('--fit-name',Math.min(max,Math.max(12,width/(measured/100-.035*(name29.textContent.length-1))*.91))+'px')};new ResizeObserver(fitName29).observe(name29.parentElement);window.addEventListener('scenechange',fitName29);window.addEventListener('resize',fitName29);document.fonts.ready.then(fitName29);fitName29();

